160	// pushResult describes what happened during a push attempt.
161	type pushResult struct {
162		// upToDate is true when the remote already had all commits (nothing transferred).
163		upToDate bool
164	}
165	
166	// parsePushResult checks git push --porcelain output for ref status flags.
167	// In porcelain mode, each ref gets a tab-delimited status line:
168	//
169	//	<flag>\t<from>:<to>\t<summary>
170	//
171	// where flag '=' means the ref was already up-to-date. This is locale-independent,
172	// unlike the human-readable "Everything up-to-date" message.
173	func parsePushResult(output string) pushResult {
174		for _, line := range strings.Split(output, "\n") {
175			if strings.HasPrefix(line, "=\t") {
176				return pushResult{upToDate: true}
177			}
178		}
179		return pushResult{upToDate: false}
180	}
181	
182	// finishPush stops the progress dots and prints "already up-to-date" or "done"
183	// depending on the push result. Only prints the settings commit hint when new
184	// content was actually pushed.
185	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
186		if result.upToDate {
187			stop(" already up-to-date")
188		} else {
189			stop(" done")
190			printSettingsCommitHint(ctx, target)
191		}
192	}
