194	// tryPushSessionsCommon attempts to push the sessions branch.
195	func tryPushSessionsCommon(ctx context.Context, remote, branchName string) (pushResult, error) {
196		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
197		defer cancel()
198	
199		// Use --no-verify to prevent recursive hook calls.
200		// Use --porcelain for machine-readable, locale-independent output.
201		cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", "--porcelain", remote, branchName)
202	
203		output, err := cmd.CombinedOutput()
204		outputStr := string(output)
205		if err != nil {
206			// Check if it's a non-fast-forward error (we can try to recover)
207			if strings.Contains(outputStr, "non-fast-forward") ||
208				strings.Contains(outputStr, "rejected") {
209				return pushResult{}, errors.New("non-fast-forward")
210			}
211			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
212		}
213	
214		return parsePushResult(outputStr), nil
215	}
