217	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
218	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
219	// always apply cleanly.
220	// The target can be a remote name or a URL.
221	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
222		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
223		defer cancel()
224	
225		fetchTarget, err := ResolveFetchTarget(ctx, target)
226		if err != nil {
227			return fmt.Errorf("resolve fetch target: %w", err)
228		}
229	
230		// Determine fetch refspec. When the resolved fetch target is a URL, use a
231		// temp ref; when it's still a remote name, use the standard remote-tracking
232		// ref.
233		var fetchedRefName plumbing.ReferenceName
234		var refSpec string
235		usedTempRef := isURL(fetchTarget)
236		if usedTempRef {
237			tmpRef := "refs/entire-fetch-tmp/" + branchName
238			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
239			fetchedRefName = plumbing.ReferenceName(tmpRef)
240		} else {
241			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
242			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
243		}
244	
245		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
246		// Use --filter=blob:none for a partial fetch that downloads only commits
247		// and trees, skipping blobs. The merge only needs the tree structure to
248		// combine entries; blobs are already local or fetched on demand.
249		fetchArgs := AppendFetchFilterArgs(ctx, []string{"fetch", "--no-tags", fetchTarget, refSpec})
250		fetchCmd := CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
251		if output, err := fetchCmd.CombinedOutput(); err != nil {
252			return fmt.Errorf("fetch failed: %s", output)
253		}
254	
255		repo, err := OpenRepository(ctx)
256		if err != nil {
257			return fmt.Errorf("failed to open git repository: %w", err)
258		}
259	
260		// Reconcile disconnected metadata branches before rebasing.
261		// The fetch above updated the remote-tracking ref, so reconciliation
262		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
263		// this cherry-picks local commits onto remote tip, updating the local ref.
264		// If reconciliation fails, abort — proceeding to rebase on disconnected
265		// branches would silently combine unrelated histories.
266		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
267			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
268		}
269	
270		// Get local branch (re-read after potential reconciliation update)
271		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
272		if err != nil {
273			return fmt.Errorf("failed to get local ref: %w", err)
274		}
275	
276		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
277		remoteRef, err := repo.Reference(fetchedRefName, true)
278		if err != nil {
279			return fmt.Errorf("failed to get remote ref: %w", err)
280		}
281	
282		// If local is already at or behind remote, fast-forward
283		if localRef.Hash() == remoteRef.Hash() {
284			return nil
285		}
286	
287		// Find merge base
288		repoPath, err := getRepoPath(repo)
289		if err != nil {
290			return fmt.Errorf("failed to get repo path: %w", err)
291		}
292		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
293		if err != nil {
294			return fmt.Errorf("failed to find merge base: %w", err)
295		}
296	
297		// If local is ancestor of remote (merge base == local), fast-forward to remote
298		if mergeBase == localRef.Hash() {
299			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
300			if err := repo.Storer.SetReference(ref); err != nil {
301				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
302			}
303			if usedTempRef {
304				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
305			}
306			return nil
307		}
308	
309		// Collect commits reachable from local but not from remote and cherry-pick
310		// them onto the remote tip. This preserves local-only commits even when the
311		// local metadata branch already contains old merge commits, while avoiding
312		// replaying shared ancestors older than the true merge-base.
313		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
314		if err != nil {
315			return fmt.Errorf("failed to collect local commits: %w", err)
316		}
317	
318		if len(localCommits) == 0 {
319			// No local-only commits — just point to remote
320			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
321			if err := repo.Storer.SetReference(ref); err != nil {
322				return fmt.Errorf("failed to update branch ref: %w", err)
323			}
324			if usedTempRef {
325				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
326			}
327			return nil
328		}
329	
330		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
331		if err != nil {
332			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
333		}
334	
335		// Update branch ref
336		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
337		if err := repo.Storer.SetReference(newRef); err != nil {
338			return fmt.Errorf("failed to update branch ref: %w", err)
339		}
340	
341		// Clean up temp ref if we used one (best-effort, not critical if it fails)
342		if usedTempRef {
343			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
344		}
345	
346		return nil
347	}
