402	// startProgressDots prints dots to w every second until the returned stop function
403	// is called. The stop function prints the given suffix and a newline.
404	func startProgressDots(w io.Writer) func(suffix string) {
405		done := make(chan struct{})
406		stopped := make(chan struct{})
407		go func() {
408			defer close(stopped)
409			ticker := time.NewTicker(time.Second)
410			defer ticker.Stop()
411			for {
412				select {
413				case <-done:
414					return
415				case <-ticker.C:
416					fmt.Fprint(w, ".")
417				}
418			}
419		}()
420		return func(suffix string) {
421			close(done)
422			<-stopped // Wait for goroutine to finish before writing suffix
423			fmt.Fprintln(w, suffix)
424		}
425	}
