43	// tryPushRef attempts to push a custom ref using an explicit refspec.
44	func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) (pushResult, error) {
45		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
46		defer cancel()
47	
48		// Use --no-verify to prevent recursive hook calls (this runs inside pre-push).
49		// Use --porcelain for machine-readable, locale-independent output.
50		refSpec := fmt.Sprintf("%s:%s", refName, refName)
51		cmd := CheckpointGitCommand(ctx, target, "push", "--no-verify", "--porcelain", target, refSpec)
52	
53		output, err := cmd.CombinedOutput()
54		outputStr := string(output)
55		if err != nil {
56			if strings.Contains(outputStr, "non-fast-forward") ||
57				strings.Contains(outputStr, "rejected") {
58				return pushResult{}, errors.New("non-fast-forward")
59			}
60			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
61		}
62	
63		return parsePushResult(outputStr), nil
64	}
