66	// doPushRef pushes a custom ref with fetch+merge recovery on conflict.
67	func doPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
68		displayTarget := target
69		if isURL(target) {
70			displayTarget = "checkpoint remote"
71		}
72	
73		shortRef := shortRefName(refName)
74		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
75		stop := startProgressDots(os.Stderr)
76	
77		if result, err := tryPushRef(ctx, target, refName); err == nil {
78			finishPush(ctx, stop, result, target)
79			return nil
80		}
81		stop("")
82	
83		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", shortRef)
84		stop = startProgressDots(os.Stderr)
85	
86		if err := fetchAndMergeRef(ctx, target, refName); err != nil {
87			stop("")
88			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", shortRef, err)
89			printCheckpointRemoteHint(target)
90			return nil
91		}
92		stop(" done")
93	
94		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
95		stop = startProgressDots(os.Stderr)
96	
97		if result, err := tryPushRef(ctx, target, refName); err != nil {
98			stop("")
99			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", shortRef, err)
100			printCheckpointRemoteHint(target)
101		} else {
102			finishPush(ctx, stop, result, target)
103		}
104	
105		return nil
106	}
