108	// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
109	// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
110	//
111	// For /full/current: if the remote has archived generations not present locally,
112	// another machine rotated. In that case, local data is merged into the latest
113	// archived generation instead of into /full/current (see handleRotationConflict).
114	func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
115		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
116		defer cancel()
117	
118		fetchTarget, err := ResolveFetchTarget(ctx, target)
119		if err != nil {
120			return fmt.Errorf("resolve fetch target: %w", err)
121		}
122	
123		// Fetch to a temp ref
124		tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
125		tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
126		refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
127	
128		// Use --filter=blob:none for a partial fetch that downloads only commits
129		// and trees, skipping blobs. The merge only needs the tree structure to
130		// combine entries; blobs are already local or fetched on demand.
131		fetchArgs := AppendFetchFilterArgs(ctx, []string{"fetch", "--no-tags", fetchTarget, refSpec})
132		fetchCmd := CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
133		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
134		if output, err := fetchCmd.CombinedOutput(); err != nil {
135			return fmt.Errorf("fetch failed: %s", output)
136		}
137	
138		repo, err := OpenRepository(ctx)
139		if err != nil {
140			return fmt.Errorf("failed to open repository: %w", err)
141		}
142		defer func() {
143			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
144		}()
145	
146		// Check for rotation conflict on /full/current
147		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
148			remoteOnlyArchives, detectErr := detectRemoteOnlyArchives(ctx, target, repo)
149			if detectErr == nil && len(remoteOnlyArchives) > 0 {
150				return handleRotationConflict(ctx, target, fetchTarget, repo, refName, tmpRefName, remoteOnlyArchives)
151			}
152		}
153	
154		// Standard tree merge (no rotation detected)
155		localRef, err := repo.Reference(refName, true)
156		if err != nil {
157			return fmt.Errorf("failed to get local ref: %w", err)
158		}
159		localCommit, err := repo.CommitObject(localRef.Hash())
160		if err != nil {
161			return fmt.Errorf("failed to get local commit: %w", err)
162		}
163		localTree, err := localCommit.Tree()
164		if err != nil {
165			return fmt.Errorf("failed to get local tree: %w", err)
166		}
167	
168		remoteRef, err := repo.Reference(tmpRefName, true)
169		if err != nil {
170			return fmt.Errorf("failed to get remote ref: %w", err)
171		}
172		remoteCommit, err := repo.CommitObject(remoteRef.Hash())
173		if err != nil {
174			return fmt.Errorf("failed to get remote commit: %w", err)
175		}
176		remoteTree, err := remoteCommit.Tree()
177		if err != nil {
178			return fmt.Errorf("failed to get remote tree: %w", err)
179		}
180	
181		entries := make(map[string]object.TreeEntry)
182		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
183			return fmt.Errorf("failed to flatten local tree: %w", err)
184		}
185		if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
186			return fmt.Errorf("failed to flatten remote tree: %w", err)
187		}
188	
189		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
190		if err != nil {
191			return fmt.Errorf("failed to build merged tree: %w", err)
192		}
193	
194		mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
195			[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
196			"Merge remote "+shortRefName(refName))
197		if err != nil {
198			return fmt.Errorf("failed to create merge commit: %w", err)
199		}
200	
201		newRef := plumbing.NewHashReference(refName, mergeCommitHash)
202		if err := repo.Storer.SetReference(newRef); err != nil {
203			return fmt.Errorf("failed to update ref: %w", err)
204		}
205	
206		return nil
207	}
