248	// handleRotationConflict handles the case where remote /full/current was rotated.
249	// Merges local /full/current into the latest remote archived generation to avoid
250	// duplicating checkpoint data, then adopts remote's /full/current as local.
251	func handleRotationConflict(ctx context.Context, target, fetchTarget string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
252		// Use the latest remote-only archive
253		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
254		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
255	
256		// Fetch the latest archived generation
257		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
258		archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
259		fetchArgs := AppendFetchFilterArgs(ctx, []string{"fetch", "--no-tags", fetchTarget, archiveRefSpec})
260		fetchCmd := CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
261		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
262		if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
263			return fmt.Errorf("fetch archived generation failed: %s", output)
264		}
265		defer func() {
266			_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
267		}()
268	
269		// Get archived generation state
270		archiveRef, err := repo.Reference(archiveTmpRef, true)
271		if err != nil {
272			return fmt.Errorf("failed to get archived ref: %w", err)
273		}
274		archiveCommit, err := repo.CommitObject(archiveRef.Hash())
275		if err != nil {
276			return fmt.Errorf("failed to get archive commit: %w", err)
277		}
278		archiveTree, err := archiveCommit.Tree()
279		if err != nil {
280			return fmt.Errorf("failed to get archive tree: %w", err)
281		}
282	
283		// Get local /full/current state
284		localRef, err := repo.Reference(refName, true)
285		if err != nil {
286			return fmt.Errorf("failed to get local ref: %w", err)
287		}
288		localCommit, err := repo.CommitObject(localRef.Hash())
289		if err != nil {
290			return fmt.Errorf("failed to get local commit: %w", err)
291		}
292		localTree, err := localCommit.Tree()
293		if err != nil {
294			return fmt.Errorf("failed to get local tree: %w", err)
295		}
296	
297		// Tree-merge local /full/current into archived generation.
298		// Git content-addressing deduplicates shared shard paths automatically.
299		entries := make(map[string]object.TreeEntry)
300		if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
301			return fmt.Errorf("failed to flatten archive tree: %w", err)
302		}
303		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
304			return fmt.Errorf("failed to flatten local tree: %w", err)
305		}
306	
307		// Update generation.json timestamps if present in the merged tree.
308		// Use the local /full/current HEAD commit time as the newest checkpoint time
309		// (more accurate than time.Now() for cleanup scheduling).
310		if genEntry, exists := entries[paths.GenerationFileName]; exists {
311			if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
312				entries[paths.GenerationFileName] = updatedEntry
313			} else {
314				logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
315					slog.String("error", updateErr.Error()),
316				)
317			}
318		}
319	
320		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
321		if err != nil {
322			return fmt.Errorf("failed to build merged tree: %w", err)
323		}
324	
325		// Create commit parented on archive's commit (fast-forward)
326		mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
327			[]plumbing.Hash{archiveRef.Hash()},
328			"Merge local checkpoints into archived generation")
329		if err != nil {
330			return fmt.Errorf("failed to create merge commit: %w", err)
331		}
332	
333		// Update local archived ref and push it
334		newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
335		if err := repo.Storer.SetReference(newArchiveRef); err != nil {
336			return fmt.Errorf("failed to update archive ref: %w", err)
337		}
338	
339		if _, pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
340			return fmt.Errorf("failed to push updated archive: %w", pushErr)
341		}
342	
343		// Adopt remote's /full/current as local
344		remoteRef, err := repo.Reference(tmpRefName, true)
345		if err != nil {
346			return fmt.Errorf("failed to get fetched /full/current: %w", err)
347		}
348		adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
349		if err := repo.Storer.SetReference(adoptedRef); err != nil {
350			return fmt.Errorf("failed to adopt remote /full/current: %w", err)
351		}
352	
353		return nil
354	}
