356	// updateGenerationTimestamps reads generation.json from a blob, updates
357	// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
358	// an updated tree entry. Uses the local commit timestamp rather than
359	// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
360	func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
361		blob, err := repo.BlobObject(genBlobHash)
362		if err != nil {
363			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
364		}
365		reader, err := blob.Reader()
366		if err != nil {
367			return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
368		}
369		defer reader.Close()
370	
371		data, err := io.ReadAll(reader)
372		if err != nil {
373			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
374		}
375	
376		var gen checkpoint.GenerationMetadata
377		if err := json.Unmarshal(data, &gen); err != nil {
378			return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
379		}
380	
381		if newestFromLocal.After(gen.NewestCheckpointAt) {
382			gen.NewestCheckpointAt = newestFromLocal
383		}
384	
385		updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
386		if err != nil {
387			return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
388		}
389	
390		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
391		if err != nil {
392			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
393		}
394	
395		return object.TreeEntry{
396			Name: paths.GenerationFileName,
397			Mode: filemode.Regular,
398			Hash: newBlobHash,
399		}, nil
400	}
