402	// pushV2Refs pushes v2 checkpoint refs to the target.
403	// Pushes /main, /full/current, and the latest archived generation (if any).
404	// Older archived generations are immutable and were pushed when created.
405	func pushV2Refs(ctx context.Context, target string) {
406		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
407		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally
408	
409		// Push only the latest archived generation (most likely to be newly created)
410		repo, err := OpenRepository(ctx)
411		if err != nil {
412			return
413		}
414		store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
415		archived, err := store.ListArchivedGenerations()
416		if err != nil || len(archived) == 0 {
417			return
418		}
419		latest := archived[len(archived)-1]
420		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
421	}
