100	// isValidToken returns false if the token contains control characters (bytes < 0x20
101	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
102	// embedded in the token value.
103	func isValidToken(token string) bool {
104		for _, b := range []byte(token) {
