290	func (s *ManualCommitStrategy) Rewind(ctx context.Context, w, errW io.Writer, point RewindPoint) error {
291		repo, err := OpenRepository(ctx)
292		if err != nil {
293			return fmt.Errorf("failed to open git repository: %w", err)
294		}
295	
296		// Get the checkpoint commit
297		commitHash := plumbing.NewHash(point.ID)
298		commit, err := repo.CommitObject(commitHash)
299		if err != nil {
300			return fmt.Errorf("failed to get commit: %w", err)
301		}
302	
303		tree, err := commit.Tree()
304		if err != nil {
305			return fmt.Errorf("failed to get tree: %w", err)
306		}
307	
308		// Reset the shadow branch to the rewound checkpoint
309		// This ensures the next checkpoint will only include prompts from this point forward
