// isURL returns true if the target is a direct URL or filesystem path rather
// than a git remote name. A git remote name is a simple identifier (letters,
// digits, hyphens, underscores, dots); anything containing `/` or `\` is a
// path, and anything containing `://` or `@` is a URL. Callers use this to
// decide whether to treat the target as a direct push destination (no
// remote-tracking refs) vs. a configured remote (with tracking refs).
func isURL(target string) bool {
	return strings.ContainsAny(target, `/\`) ||
		strings.Contains(target, "://") ||
		strings.Contains(target, "@")
}

