383	// EnsureMetadataBranch creates or updates the local entire/checkpoints/v1 branch.
384	// If the remote-tracking branch (origin/entire/checkpoints/v1) exists and the local
385	// branch is missing or empty, creates/updates the local branch from it.
386	// Otherwise creates an empty orphan.
387	func EnsureMetadataBranch(repo *git.Repository) error {
388		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
389	
390		// Check if remote-tracking branch exists (e.g., after clone/fetch)
391		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
392		remoteRef, remoteErr := repo.Reference(remoteRefName, true)
393		if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
394			return fmt.Errorf("failed to check remote metadata branch: %w", remoteErr)
395		}
396	
397		// Check if local branch already exists
398		localRef, err := repo.Reference(refName, true)
399		if err == nil {
400			if remoteErr == nil && localRef.Hash() != remoteRef.Hash() {
401				// Local and remote exist but differ — determine relationship
402				isEmpty, checkErr := isEmptyMetadataBranch(repo, localRef)
403				if checkErr != nil {
404					return fmt.Errorf("failed to check metadata branch contents: %w", checkErr)
405				}
406				if isEmpty {
407					// Empty orphan — just point to remote
408					ref := plumbing.NewHashReference(refName, remoteRef.Hash())
409					if setErr := repo.Storer.SetReference(ref); setErr != nil {
410						return fmt.Errorf("failed to update metadata branch from remote: %w", setErr)
411					}
412					fmt.Fprintf(os.Stderr, "[entire] Updated local branch '%s' from origin\n", paths.MetadataBranchName)
413				} else {
414					// Local has real data and differs from remote — if disconnected
415					// (no common ancestor), reconciliation happens at pre-push time
416					// or via 'entire doctor'. Read paths warn but do not auto-fix.
417					logging.Debug(context.Background(), "metadata branch differs from remote, reconciliation deferred to read/write time",
418						"local_hash", localRef.Hash().String()[:7],
419						"remote_hash", remoteRef.Hash().String()[:7],
420					)
421				}
422			}
423			return nil
424		}
425		if !errors.Is(err, plumbing.ErrReferenceNotFound) {
426			return fmt.Errorf("failed to check metadata branch: %w", err)
427		}
428	
429		// Local branch doesn't exist — create from remote if available
430		if remoteErr == nil {
431			ref := plumbing.NewHashReference(refName, remoteRef.Hash())
432			if err := repo.Storer.SetReference(ref); err != nil {
433				return fmt.Errorf("failed to create metadata branch from remote: %w", err)
434			}
435			fmt.Fprintf(os.Stderr, "✓ Created local branch '%s' from origin\n", paths.MetadataBranchName)
436			return nil
437		}
438	
439		// No local or remote branch — create empty orphan
440		emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
441		obj := repo.Storer.NewEncodedObject()
442		if err := emptyTree.Encode(obj); err != nil {
443			return fmt.Errorf("failed to encode empty tree: %w", err)
444		}
445		emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
446		if err != nil {
447			return fmt.Errorf("failed to store empty tree: %w", err)
448		}
449		emptyTreeHash, err = vercelconfig.MaybeMergeMetadataBranchConfig(repo, emptyTreeHash)
450		if err != nil {
451			return fmt.Errorf("failed to initialize metadata branch vercel config: %w", err)
452		}
453	
454		// Create orphan commit (no parent)
455		now := time.Now()
456		authorName, authorEmail := GetGitAuthorFromRepo(repo)
457		sig := object.Signature{
458			Name:  authorName,
459			Email: authorEmail,
460			When:  now,
461		}
462	
463		commit := &object.Commit{
464			TreeHash:  emptyTreeHash,
465			Author:    sig,
466			Committer: sig,
467			Message:   "Initialize metadata branch\n\nThis branch stores session metadata.\n",
468		}
469		// Note: No ParentHashes - this is an orphan commit
470	
471		commitObj := repo.Storer.NewEncodedObject()
472		if err := commit.Encode(commitObj); err != nil {
473			return fmt.Errorf("failed to encode orphan commit: %w", err)
474		}
475		commitHash, err := repo.Storer.SetEncodedObject(commitObj)
476		if err != nil {
477			return fmt.Errorf("failed to store orphan commit: %w", err)
478		}
479	
480		// Create branch reference
481		ref := plumbing.NewHashReference(refName, commitHash)
482		if err := repo.Storer.SetReference(ref); err != nil {
483			return fmt.Errorf("failed to create metadata branch: %w", err)
484		}
485	
486		fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
487		return nil
488	}
